        ["LoginInvalid"] = ["Логин должен быть от 3 до 32 символов: латинские буквы, цифры и знаки . - _", "A login is 3 to 32 characters: Latin letters, digits and . - _", "Մուտքանունը պետք է լինի 3-ից 32 նիշ՝ լատինական տառեր, թվեր և . - _ նշաններ։"],
        ["LoginTaken"] = ["Такой логин уже занят, придумайте другой.", "That login is taken, please choose another one.", "Այս մուտքանունն արդեն զբաղված է, ընտրեք մեկ ուրիշը։"],
        ["PasswordHint"] = ["Не короче 6 символов. По логину и паролю вы будете входить с любого устройства.", "At least 6 characters. You will sign in with your login and password from any device.", "Առնվազն 6 նիշ։ Մուտքանունով և գաղտնաբառով մուտք կգործեք ցանկացած սարքից։"],
        ["PasswordRepeat"] = ["Пароль ещё раз", "Password again", "Կրկնեք գաղտնաբառը"],
        ["PasswordShort"] = ["Пароль должен быть не короче 6 символов.", "The password must be at least 6 characters long.", "Գաղտնաբառը պետք է լինի առնվազն 6 նիշ։"],
        ["PasswordMismatch"] = ["Пароли не совпадают.", "The passwords don't match.", "Գաղտնաբառերը չեն համընկնում։"],
        ["LoginButton"] = ["Войти", "Sign in", "Մուտք գործել"],
        ["LoginFailed"] = ["Неверная почта или пароль.", "Wrong e-mail or password.", "Էլ. փոստը կամ գաղտնաբառը սխալ է։"],
        ["SignInId"] = ["Почта", "E-mail", "Էլ. փոստ"],
        ["SignupEmailHint"] = ["По ней вы будете входить в игру. Придёт письмо со ссылкой: участником вы станете, когда откроете её. Адрес видите только вы.", "You'll sign in with it. We'll e-mail you a link: you're in the game once you open it. Only you can see the address.", "Դրանով մուտք կգործեք խաղ։ Կուղարկենք հղումով նամակ․ մասնակից կդառնաք, երբ բացեք այն։ Հասցեն տեսնում եք միայն դուք։"],
        ["EmailLoginHint"] = ["По ней вы будете входить в игру. Адрес видите только вы.", "You'll sign in with it. Only you can see the address.", "Դրանով մուտք կգործեք խաղ։ Հասցեն տեսնում եք միայն դուք։"],
        ["MailTaken"] = ["Этот адрес уже есть в игре. Войдите с ним или восстановите пароль.", "This address is already in the game. Sign in with it or reset the password.", "Այս հասցեն արդեն կա խաղում։ Մուտք գործեք դրանով կամ վերականգնեք գաղտնաբառը։"],
        ["SignupSent"] = ["Письмо отправлено на {0}. Откройте ссылку из него, чтобы попасть в игру: она действует сутки. Если письма нет, проверьте папку «Спам».", "An e-mail went to {0}. Open the link in it to get into the game; it works for a day. If it isn't there, check the spam folder.", "Նամակն ուղարկվել է {0} հասցեին։ Խաղ մտնելու համար բացեք դրա հղումը․ այն գործում է մեկ օր։ Եթե նամակը չկա, ստուգեք «Սպամ» թղթապանակը։"],
        ["SignupPending"] = ["Почта ещё не подтверждена: откройте ссылку из письма. Если письма нет, зарегистрируйтесь ещё раз.", "This address isn't confirmed yet: open the link in the e-mail. If there's no e-mail, sign up again.", "Հասցեն դեռ հաստատված չէ․ բացեք նամակի հղումը։ Եթե նամակ չկա, նորից գրանցվեք։"],
        ["SignupTitle"] = ["Завершение регистрации", "Finish signing up", "Գրանցման ավարտ"],
        ["SignupText"] = ["Присоединиться к Тайному Санте под именем «{0}» с почтой {1}?", "Join Secret Santa as \"{0}\" with the address {1}?", "Միանա՞լ Գաղտնի Ձմեռ պապին «{0}» անունով և {1} հասցեով։"],
        ["SignupButton"] = ["Войти в игру", "Join the game", "Միանալ խաղին"],
        ["SignupExpired"] = ["Ссылка устарела: она действовала сутки. Зарегистрируйтесь ещё раз.", "This link has expired: it worked for a day. Please sign up again.", "Հղումը հնացել է․ այն գործում էր մեկ օր։ Խնդրում ենք նորից գրանցվել։"],
        ["SignupNameTaken"] = ["Пока письмо шло, имя «{0}» занял другой участник. Зарегистрируйтесь ещё раз с другим именем.", "While the e-mail was on its way, someone else took the name \"{0}\". Please sign up again with another name.", "Մինչ նամակը կհասներ, «{0}» անունը զբաղեցրել է մեկ այլ մասնակից։ Խնդրում ենք նորից գրանցվել այլ անունով։"],
        ["SignupsWaiting"] = ["Ждут подтверждения почты: {0}", "Waiting for their e-mail confirmation: {0}", "Սպասում են էլ. փոստի հաստատման՝ {0}"],
        ["LoginLocked"] = ["Слишком много неудачных попыток. Попробуйте через 15 минут или попросите организатора сбросить пароль.", "Too many failed attempts. Try again in 15 minutes or ask the organizer to reset your password.", "Չափազանց շատ անհաջող փորձեր։ Փորձեք 15 րոպե անց կամ խնդրեք կազմակերպչին զրոյացնել ձեր գաղտնաբառը։"],
        ["LoginNoPassword"] = ["Пароль для этого участника ещё не задан. Задайте его по своей личной ссылке или по ссылке от организатора.", "No password is set for this participant yet. Set one through your personal link or the link from the organizer.", "Այս մասնակցի գաղտնաբառը դեռ սահմանված չէ։ Սահմանեք այն ձեր անձնական հղումով կամ կազմակերպչից ստացած հղումով։"],
        ["ForgotTitle"] = ["Забыли пароль?", "Forgot your password?", "Մոռացե՞լ եք գաղտնաբառը"],
        ["ForgotHint"] = ["Если к вашему участию привязана почта, пришлём на неё ссылку для нового пароля. Если почты нет, попросите организатора сбросить пароль.", "If an e-mail address is linked to your sign-in, we'll send a link for a new password there. If not, ask the organizer to reset your password.", "Եթե ձեր մասնակցությանը կապված է էլ. փոստ, այնտեղ կուղարկենք նոր գաղտնաբառի հղումը։ Եթե չկա, խնդրեք կազմակերպչին զրոյացնել գաղտնաբառը։"],
        ["ForgotButton"] = ["Прислать ссылку", "Send the link", "Ուղարկել հղումը"],
        ["ForgotSent"] = ["Если такой участник есть и к нему привязана почта, ссылка для нового пароля уже отправлена. Если письмо не пришло, проверьте папку «Спам» или попросите организатора сбросить пароль.", "If there is such a participant with a linked address, a link for a new password is on its way. If it doesn't arrive, check the spam folder or ask the organizer to reset your password.", "Եթե այդպիսի մասնակից կա, և նրան կապված է էլ. փոստ, նոր գաղտնաբառի հղումն արդեն ուղարկված է։ Եթե նամակը չգա, ստուգեք «Սպամ» թղթապանակը կամ խնդրեք կազմակերպչին զրոյացնել գաղտնաբառը։"],
        ["ResetEnterTitle"] = ["Новый пароль", "New password", "Նոր գաղտնաբառ"],
        ["ResetEnterText"] = ["По этой разовой ссылке вы войдёте в игру и зададите новый пароль. Старый пароль перестанет работать, а на других устройствах вы выйдете.", "This one-time link signs you in to the game to set a new password. The old password stops working, and your other devices are signed out.", "Այս մեկանգամյա հղումով մուտք կգործեք խաղ և կսահմանեք նոր գաղտնաբառ։ Հին գաղտնաբառն այլևս չի աշխատի, և մյուս սարքերից դուրս կգաք։"],
        ["ResetEnterButton"] = ["Войти и задать пароль", "Sign in and set a password", "Մուտք գործել և սահմանել գաղտնաբառ"],
        ["ResetExpiredTitle"] = ["Ссылка устарела", "This link has expired", "Հղումը հնացել է"],
        ["ResetExpiredText"] = ["Ссылка из письма действует сутки. Запросите новую на странице входа («Забыли пароль?») или попросите организатора сбросить пароль.", "A link from an e-mail works for a day. Ask for a new one on the sign-in page (Forgot your password?) or ask the organizer to reset your password.", "Նամակի հղումը գործում է մեկ օր։ Խնդրեք նորը մուտքի էջում («Մոռացե՞լ եք գաղտնաբառը») կամ խնդրեք կազմակերպչին զրոյացնել գաղտնաբառը։"],

        ["Welcome"] = ["Готово, вы в игре! Чтобы вернуться сюда с другого устройства, откройте ссылку-приглашение и войдите по почте и паролю.", "You're in! To get back here from another device, open the invite link and sign in with your e-mail and password.", "Պատրաստ է, դուք խաղի մեջ եք։ Այլ սարքից այստեղ վերադառնալու համար բացեք հրավերի հղումը և մուտք գործեք էլ. փոստով ու գաղտնաբառով։"],
        ["CredentialsTitle"] = ["Данные для входа", "Sign-in details", "Մուտքի տվյալներ"],
        ["SetPasswordHint"] = ["С ними вы сможете входить с любого устройства через ссылку-приглашение. Ссылка, по которой вы сюда попали, после этого перестанет работать.", "With them you can sign in from any device through the invite link. The link that brought you here will then stop working.", "Դրանցով կկարողանաք մուտք գործել ցանկացած սարքից՝ հրավերի հղման միջոցով։ Այն հղումը, որով այստեղ եք եկել, այնուհետև այլևս չի աշխատի։"],
        ["SetLoginHint"] = ["Придумайте логин: дальше вы будете входить по нему и своему паролю с любого устройства через ссылку-приглашение.", "Choose a login: from now on you sign in with it and your password from any device through the invite link.", "Ընտրեք մուտքանուն․ այսուհետ մուտք կգործեք դրանով և ձեր գաղտնաբառով ցանկացած սարքից՝ հրավերի հղման միջոցով։"],
        ["PasswordSet"] = ["Сохранено. Теперь входите по логину и паролю.", "Saved. From now on, sign in with your login and password.", "Պահպանված է։ Այսուհետ մուտք գործեք մուտքանունով և գաղտնաբառով։"],
        ["YourLogin"] = ["Ваш логин: {0}", "Your login: {0}", "Ձեր մուտքանունը՝ {0}"],
        ["Logout"] = ["Выйти", "Sign out", "Դուրս գալ"],


        ["MailTitle"] = ["Почта", "E-mail", "Էլ. փոստ"],
