        ["MailLinked"] = ["Почта привязана: {0}", "Linked address: {0}", "Կապված հասցե՝ {0}"],
        ["MailPending"] = ["Письмо для подтверждения отправлено на {0}. Откройте ссылку из него: она действует сутки. Если письма нет, проверьте папку «Спам».", "A confirmation e-mail went to {0}. Open the link in it; it works for a day. If it isn't there, check the spam folder.", "Հաստատման նամակն ուղարկվել է {0} հասցեին։ Բացեք դրա հղումը․ այն գործում է մեկ օր։ Եթե նամակը չկա, ստուգեք «Սպամ» թղթապանակը։"],
        ["MailAddress"] = ["Адрес почты", "E-mail address", "Էլ. փոստի հասցե"],
        ["MailSend"] = ["Прислать письмо для подтверждения", "Send a confirmation e-mail", "Ուղարկել հաստատման նամակ"],
        ["MailRemove"] = ["Отвязать почту", "Unlink the address", "Հեռացնել հասցեն"],
        ["MailInvalid"] = ["Проверьте адрес: похоже, в нём ошибка.", "Please check the address: it doesn't look right.", "Ստուգեք հասցեն․ կարծես սխալ կա։"],
        ["MailSame"] = ["Этот адрес уже привязан.", "This address is already linked.", "Այս հասցեն արդեն կապված է։"],
        ["MailUsed"] = ["Этот адрес уже привязан к другому участнику игры.", "This address already belongs to another participant in the game.", "Այս հասցեն արդեն պատկանում է խաղի մեկ այլ մասնակցի։"],
        ["MailWait"] = ["Письмо только что отправлено. Новое можно запросить через несколько минут.", "An e-mail was sent a moment ago. You can ask for a new one in a few minutes.", "Նամակը հենց նոր է ուղարկվել։ Նորը կարող եք խնդրել մի քանի րոպեից։"],
        ["MailFailed"] = ["Не получилось отправить письмо. Попробуйте ещё раз чуть позже.", "The e-mail couldn't be sent. Please try again a bit later.", "Նամակը չհաջողվեց ուղարկել։ Փորձեք կրկին մի փոքր ուշ։"],
        ["MailConfirmTitle"] = ["Подтверждение почты", "Confirm the e-mail address", "Էլ. փոստի հաստատում"],
        ["MailConfirmText"] = ["Привязать {0} к участнику «{1}» в Тайном Санте? На этот адрес придут письма о жеребьёвке и новых сообщениях и ссылка для нового пароля, если старый забудется.", "Link {0} to \"{1}\" in Secret Santa? E-mails about the draw and new messages will come to this address, and so will a link for a new password if it is forgotten.", "Կապե՞լ {0} հասցեն Գաղտնի Ձմեռ պապի «{1}» մասնակցին։ Այս հասցեին կգան նամակներ վիճակահանության և նոր հաղորդագրությունների մասին, իսկ եթե գաղտնաբառը մոռացվի՝ նորի հղումը։"],
        ["MailConfirmButton"] = ["Подтвердить", "Confirm", "Հաստատել"],
        ["MailConfirmed"] = ["Готово: почта {0} привязана.", "Done: {0} is linked.", "Պատրաստ է․ {0} հասցեն կապված է։"],
        ["MailLinkExpired"] = ["Ссылка устарела: она действовала сутки. Запросите новое письмо на своей странице.", "This link has expired: it worked for a day. Ask for a new e-mail on your page.", "Հղումը հնացել է․ այն գործում էր մեկ օր։ Խնդրեք նոր նամակ ձեր էջում։"],
        ["MailConfirmSubject"] = ["Тайный Санта: подтвердите почту", "Secret Santa: confirm your e-mail address", "Գաղտնի Ձմեռ պապ․ հաստատեք էլ. փոստը"],
        ["MailConfirmBody"] = ["Здравствуйте, {0}!\n\nЧтобы привязать этот адрес к своему участию в Тайном Санте, откройте ссылку и нажмите «Подтвердить»:\n{1}\n\nСсылка действует сутки. Если вы ничего не привязывали, просто удалите это письмо.", "Hi {0},\n\nTo link this address to your Secret Santa sign-in, open the link and press Confirm:\n{1}\n\nThe link works for a day. If you didn't ask for this, just delete this e-mail.", "Բարև ձեզ, {0}։\n\nԱյս հասցեն Գաղտնի Ձմեռ պապում ձեր մասնակցությանը կապելու համար բացեք հղումը և սեղմեք «Հաստատել»․\n{1}\n\nՀղումը գործում է մեկ օր։ Եթե դուք ոչինչ չեք կապել, պարզապես ջնջեք այս նամակը։"],
        ["MailResetSubject"] = ["Тайный Санта: новый пароль", "Secret Santa: a new password", "Գաղտնի Ձմեռ պապ․ նոր գաղտնաբառ"],
        ["MailResetBody"] = ["Здравствуйте, {0}!\n\nКто-то, скорее всего вы, попросил ссылку для нового пароля в Тайном Санте. Откройте её и нажмите «Войти и задать пароль»:\n{1}\n\nСсылка разовая и действует сутки. Если вы ничего не просили, ничего не делайте: пароль останется прежним.", "Hi {0},\n\nSomeone, most likely you, asked for a link to set a new Secret Santa password. Open it and press \"Sign in and set a password\":\n{1}\n\nThe link works once and for a day. If you didn't ask for it, do nothing: your password stays as it is.", "Բարև ձեզ, {0}։\n\nԻնչ-որ մեկը, ամենայն հավանականությամբ դուք, խնդրել է Գաղտնի Ձմեռ պապի նոր գաղտնաբառի հղում։ Բացեք այն և սեղմեք «Մուտք գործել և սահմանել գաղտնաբառ»․\n{1}\n\nՀղումը մեկանգամյա է և գործում է մեկ օր։ Եթե դուք ոչինչ չեք խնդրել, ոչինչ մի՛ արեք․ գաղտնաբառը կմնա նույնը։"],
